using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public sealed class ConfigResources
{
    // A direct (non-templated) resource — listed via resources/list.
    [McpServerResource(UriTemplate = "config://app/settings", Name = "app-settings",
        MimeType = "application/json"),
     Description("Returns the application configuration settings.")]
    public static string GetAppSettings()
    {
        var config = new
        {
            Version = "1.0.0",
            Environment = "Production",
            MaxConnections = 100,
            Features = new { DarkMode = true, BetaAccess = false }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    // A templated resource — listed via resources/templates/list.
    // The {section} placeholder is bound to the method parameter.
    [McpServerResource(UriTemplate = "config://app/{section}", Name = "app-config-section",
        MimeType = "application/json"),
     Description("Returns configuration for a specific section.")]
    public static string GetConfigSection(string section)
    {
        var sections = new Dictionary<string, object>
        {
            ["logging"] = new { Level = "Information", EnableConsole = true },
            ["database"] = new { ConnectionTimeout = 30, MaxPoolSize = 50 },
            ["cache"] = new { Enabled = true, TtlMinutes = 15 }
        };

        if (!sections.TryGetValue(section.ToLowerInvariant(), out var data))
        {
            return JsonSerializer.Serialize(new { Error = $"Unknown section: {section}" });
        }

        return JsonSerializer.Serialize(data, new JsonSerializerOptions { WriteIndented = true });
    }
}

